fn put64(out:&mut [u8],p:usize,x:i64){out[p..p+8].copy_from_slice(&x.to_le_bytes());}
#[no_mangle] pub unsafe extern "C" fn edn_iir_cascade(raw:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if raw.is_null()||n<2||n>50{return -1}let v=unsafe{std::slice::from_raw_parts(raw,n)};let count=v[0];let mut x=v[1];if !(1..=8).contains(&count)||!(-1024..=1023).contains(&x)||n!=2+6*count as usize{return -1}let q=count as usize;let mut c=[0i64;32];let mut s=[0i64;16];for i in 0..4*q{c[i]=v[2+i];if !(-1024..=1023).contains(&c[i]){return -1}}for i in 0..2*q{s[i]=v[2+4*q+i];if !(-1024..=1023).contains(&s[i]){return -1}}let bytes=8*(1+2*q);if out.is_null()||cap<bytes{return -2}for i in 0..q{let t=x+((c[4*i+2]*s[2*i]+c[4*i+3]*s[2*i+1])>>15);x=t+((c[4*i]*s[2*i]+c[4*i+1]*s[2*i+1])>>15);s[2*i+1]=s[2*i];s[2*i]=t}let output=unsafe{std::slice::from_raw_parts_mut(out,bytes)};put64(output,0,x);for i in 0..2*q{put64(output,8*(i+1),s[i])}bytes as i64}
